window.MONSTER_CHUNK_61 = [{"name":"Desert Hermit","cr":8,"xp":4800,"race":"Human","classes":[{"class":"druid","level":9}],"alignment":"N","size":"Medium","type":"humanoid","subtypes":["human"],"init":3,"ac":18,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+3 armor, +1 deflection, +3 Dex, +1 dodge","hp":80,"hd":"9d8+36","hdvalue":9,"fort":8,"ref":6,"will":32,"save_mods":"+4 vs. fey and plant-targeted effects","defensive_abilities":["heat shimmer (6 rounds, DC 17)"],"immunities":["poison"],"speed":[{"type":"land","speed":30}],"melee":"mwk scimitar +9 (1d6+2/18-20)","ranged":"sling +9 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"wild shape","details":"3/day"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"lesser planar ally","details":"janni only"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":9,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":5,"spell_slots":1,"spells":[{"spell":"control winds"},{"spell":"transmute rock to mud","type":"domain"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"giant vermin"},{"spell":"hallucinatory terrain","type":"domain"},{"spell":"vermin shape II"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"burrow"},{"spell":"cup of dust","type":"domain"},{"spell":"greater magic fang"},{"spell":"neutralize poison"},{"spell":"spit venom"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"barkskin"},{"spell":"elemental speech"},{"spell":"pernicious poison"},{"spell":"resist energy"},{"spell":"shifting sand","type":"domain"},{"spell":"summon swarm"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"alter winds"},{"spell":"cloak of shade","type":"domain"},{"spell":"faerie fire"},{"spell":"feather step"},{"spell":"longstrider"},{"spell":"speak with animals"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"detect poison"},{"spell":"light"},{"spell":"virtue"}]}],"spelldomains":"Desert","strength":14,"dexterity":16,"constitution":14,"intelligence":10,"wisdom":16,"charisma":8,"baseatk":6,"cmb":8,"cmd":23,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Iron Will"},{"feat":"Natural Spell"},{"feat":"Spell Focus (transmutation)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":15},{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":15},{"skill":"Stealth","value":12},{"skill":"Survival","value":17}],"languages":["Common","Druidic","Osiriani"],"sq":[{"type":"nature bond","details":"Desert domain"},{"type":"nature sense"},{"type":"trackless step"},{"type":"wild empathy","details":"+8"},{"type":"woodland stride"}],"environments":["any (Osirion)"],"organizations":["solitary"],"treasure":"none","description_visual":"This weathered-looking desert dweller is dressed from head to toe in tan, loose-fitting robes.","source":"Osirion, Legacy Of Pharaohs","description":"A desert hermit seeks the solitude in the windswept wastes for two chief reasons. First, the hermit finds that isolation allows him to more easily experience nature's harsh beauty and raw power, which he seeks to emulate. Second, the wide open spaces provide the hermit with the freedom to experience the world without interference from human society, which is trapped in meaningless competitions to get ahead in a race toward an unhappy death plagued by debt, troublesome relationships, and arbitrary expectations enforced by shame, discrimination, and even violence.\n\nDesert hermits are often defensive and suspicious when interrupted by outsiders. They rarely form druid circles, preferring true isolation. Those who forgo their connection to the desert in favor of a bestial ally tend to select camels, cobras, jackals, and vultures.","ecology":"","habitat_society":"","gear":"+1 leather armor, mwk scimitar, sling with 10 bullets, belt of incredible dexterity +2, campfire bead, ring of protection +1, wand of cure moderate wounds [16 charges], wand of endure elements [20 charges], 40 gp"},{"name":"Destrachan","cr":8,"xp":4800,"alignment":"NE","size":"Large","type":"aberration","init":5,"senses":[{"type":"blindsight","modifier":"100 ft."}],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+1 Dex, +1 dodge, +8 natural, -1 size","hp":90,"hd":"12d8+36","hdvalue":12,"fort":9,"ref":7,"will":18,"defensive_abilities":["protection from sonics"],"immunities":["gaze attacks","visual effects","illusions","and attacks relying on sight"],"resists":[{"type":"sonic","value":30}],"speed":[{"type":"land","speed":30}],"melee":"bite +12 (2d6+4), 2 claws +12 (1d8+4)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"destructive harmonics"}],"strength":18,"dexterity":13,"constitution":16,"intelligence":13,"wisdom":18,"charisma":13,"baseatk":9,"cmb":14,"cmd":26,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":19},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":12},{"skill":"Survival","value":19}],"languages":["Common (cannot speak)"],"environments":["any underground"],"organizations":["solitary","pair","pack (3-5)"],"treasure":"incidental","description_visual":"The hunched, reptilian beast lopes on two clawed ft., its eyeless head dominated by a huge circular maw filled with jagged teeth.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Destructive Harmonics","kind":"Su","details":"A destrachan can project a blast of sonic energy in a cone up to 80 ft. long or in a 30-footradius burst centered on itself as a standard action. It can adjust the harmonics of its sonic cry to generate one of two different effects on targets within the area of effect, but can only create one of these effects with each use of this ability. The save DCs are Constitution-based. Destruction: All creatures within the area of effect of the destructive harmonics take 8d6 points of sonic damage-a DC 19 Reflex save halves this damage. If the destrachan wishes, this damage can instead deal nonlethal damage rather than sonic damage. Alternatively, the destrachan can target a single crystal, metal, stone, or wooden object within 80 ft. with this attack-that object takes 8d6 points of damage. This damage isn't halved when applied to the object's hit points, but is reduced by the object's hardness. A magical or attended object can attempt a DC 19 Reflex save to halve the damage. Pain: Rather than deal damage, the destrachan can cause intense pain and overwhelming sound to affect all creatures within the area. Targets in the area must succeed on a DC 19 Fortitude save to avoid being stunned for 1 round and deafened for 1d6 rounds."},{"type":"Protection from Sonics","kind":"Ex","details":"A destrachan gains a +4 racial bonus on all saves against sonic attacks. It is immune to the effects of its own destructive harmonics. A destrachan whose sense of hearing is impaired is effectively blinded, treating all targets as if they had total concealment."}],"description":"Despite its bestial appearance, the destrachan is in fact a creature of cunning and cruel intellect that enjoys inf licting pain and viciously toying with its prey. It has no eyes, and is completely blind, but possesses a pair of complex, tripartite ears it can adjust to different levels of sensitivity to sound, allowing the destrachan to hunt in absolute darkness as if it were able to see.\n\nDestrachans are carnivores, preferring to stalk and kill live prey, although they also feast on carrion. This habit serves them well, since they often kill more than they can immediately consume. They often hunt in packs, using a complex series of clicks, shrieks, and whistles to communicate with each other. While destrachans cannot speak, they are capable of understanding spoken languages like the common tongue, and often take pleasure in their victims' cries and pleas for mercy.","ecology":"","habitat_society":""},{"name":"Dimensional Shambler","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","evil"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+3 Dex, +8 natural","hp":94,"hd":"9d10+45","hdvalue":9,"fort":11,"ref":8,"will":7,"defensive_abilities":["resist conjuration"],"dr":"5/lawful","immunities":["summoning"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +14 (2d6+5 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"dimension mastery"},{"type":"shift planes"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dimension door"}]},{"frequency":"3/day","spells":[{"spell":"blink"},{"spell":"dimensional anchor"}]}],"strength":21,"dexterity":16,"constitution":20,"intelligence":7,"wisdom":14,"charisma":13,"baseatk":9,"cmb":24,"cmd":33,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Vital Strike"}],"skills":[{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":15}],"languages":["Aklo"],"environments":["any"],"organizations":["solitary","pair","gang (3-9)"],"treasure":"standard","description_visual":"This rugose figure rears up to a man's height, its large hands bearing far too many twitching fingers.","source":"AP 46","special_abilities":[{"type":"Dimension Mastery","kind":"Ex","details":"A dimensional shambler can take actions normally after using dimension door effects. A dimensional shambler under the effects of a dimensional anchor or dimensional lock spell can ignore the effects of the spell for 1 round by making a DC 25 Knowledge (planes) check as a move action."},{"type":"Resist Conjuration","kind":"Ex","details":"Dimensional shamblers detest being conjured by other creatures. They are immune to all spell effects of the summoning school, and are treated as if they had double their actual Hit Dice (18 HD for most dimensional shamblers) for the purposes of determining if they can be conjured by spells like planar ally or planar binding."},{"type":"Shift Planes","kind":"Su","details":"A dimensional shambler can shift between planes once per hour, using an effect that is similar to that created by the plane shift spell, save that a dimensional shambler is a master of such travel and can manifest at an exact location on its destination plane if it makes a DC 20 Knowledge (planes) check. If it exceeds this DC by 10 or more, it can place itself in such a position upon arrival that if combat immediately results from its appearance, it gains a +10 bonus on its resulting initiative check. Using shift planes is a full-round action that provokes attacks of opportunity, during which the dimensional shambler shimmers and grows increasingly transparent. A dimensional shambler can use this ability while grappling a creature-doing so doesn't provoke attacks of opportunity from the creature it is grappling. If the creature is of the dimensional shambler's size or smaller (Medium for most dimensional shamblers), that creature shifts planes with the dimensional shambler unless it makes a DC 15 Will save. The save DC is Charisma-based."}],"description":"The dimensional shambler is a vagabond of the realms between realms. With its ability to shift planes, it is no stranger to the weirdest the Great Beyond has to offer, and despite its brutish and unrefined intellect, its knowledge of the planes and the relationships between dimensions is significant indeed.\n\nA dimensional shambler is humanoid in outline, yet it moves with a weird and alien gait that gives it the appearance of a creature not in full possession of its faculties, almost as if it were drunk or horribly wounded. Yet those who mistake this shambling posture as a sign of weakness swiftly learn of their error, for the dimensional shambler is in fact quite agile-the weird lumbering cadence of its movements is simply another outward manifestation of its inhuman countenance.\n\nA dimensional shambler typically stands just over 7 ft. in height, and weighs 350 pounds.\n\nEcology As outsiders, dimensional shamblers have no need to feed-a trait that comes in handy for a creature that often finds itself adrift or lost in strange realms where food and water doesn't-or perhaps cannot-exist. They are certainly most at home in regions that function similarly to most Material Plane worlds, for their bodies are built to traverse the ground. They have no inborn ability to fly, cannot breathe water, and possess no unusual resistance to energies, and as such there are many realms throughout the Great Beyond that are dangerous or even deadly to dimensional shamblers. Yet they are masters of traveling the planes, and instinctively avoid appearing in regions that would cause them harm. More powerful dimensional shamblers often seek out magical devices to aid them in traveling the stranger and less hospitable corners of reality.\n\nThe need a dimensional shambler has for exploring the Great Beyond isn't fully understood by mortal scholars. Certainly, curiosity seems to be a large part of their drive-a dimensional shambler can spend weeks or even years simply observing a particularly unusual planar feature, such as the expulsion of raw protolife from the Positive Energy Plane into the surrounding realities, the strange semianimate heavings of an Abyssal swamp giving birth to a legion of demons, or the mind-numbing violence of a reality storm deep in the Maelstrom. As chaotic evil outsiders, they are most comfortable on planes that either have no strong alignment traits or are close to chaotic evil, yet this doesn't prevent them from exploring realms beyond.\n\nThe mind of a dimensional shambler, as with its body and mobility, isn't quite \"in tune\" with mortal expectations, and it may be that what scholars have assumed is curiosity could be some other driving force. Perhaps the race instinctively travels the Great Beyond in search of a forgotten or hidden goal, or maybe the constant change of reality is something that brings them pleasure or some strange nutrition.\n\nDimensional shamblers generally lack the wits to carry on long philosophical discussions, and are prone to attacking other creatures when they encounter them, so attempts to learn more about this mysterious race through conversation have not resulted in particularly informative results.\n\nHabitat & Society Dimensional shamblers seem to have very little interest in others of their kind. While they don't display any instinctual need for violence against others of their ilk when chance brings them together, neither do they seek out their own kind for companionship.\n\nDimensional shamblers are solitary beings, and the majority of their interactions with other forms of life are violent- they are fond of snatching creatures who are capable of comprehending their own peril and whisking them away to remote corners of the multiverse.\n\nThose few who have endured these abductions and survived to tell the tale did so either by escaping their captors and hiding, or by slaying the shamblers. In all cases, their return home has involved harrowing journeys through the Great Beyond, for the dimensional shambler is frustratingly skilled at selecting particularly remote and dangerous realms as destinations for its abductions. The fate of the majority of these victims is unknown, although circumstantial evidence indicates that the shambler itself plays a key and grisly role in the victims' doom.\n\nSpellcasters have long sought to harness the dimensional shambler's ability to accurately travel between planes.\n\nMortal magic has traditionally found this feat a difficult one to master-plane shift isn'torious for its inaccuracy, often leaving powerful effects like gate, miracle, or wish as the favored methods of safe interplanar travel. Yet the dimensional shambler seems able to navigate the unnavigable with ease, traveling between incredibly diverse and distant locations with no more difficulty than a human might have stepping out of a house into his own front yard. Unfortunately, the same mastery over dimensional travel that affords shamblers such accurate navigation allows them to resist the call of conjurers with surprising skill.\n\nIn fact, by the time most spellcasters master the magic required to lure or conjure a dimensional shambler, it is often a simpler matter to use a gate spell instead.\n\nSome conjurers claim to have developed methods of attracting dimensional shamblers more easily.\n\nThrough the use of blood sacrifice via a blade of purest metal and the application of exacting mathematical symbols or other complex combinations of runes, these spellcasters can call upon dimensional shamblers with relative ease. Unfortunately, the exact combination of runes, metals, and bloodshed seems different for every dimensional shambler, so once a spellcaster discovers the correct combination to lure one of these monsters, the secret that caster has uncovered is as closely guarded as her greatest treasures. The nature and availability of these secret rituals are left to the GM to determine, but such a ritual's recipe could well be worth 8,000 gp or more to an interested party.","ecology":"As outsiders, dimensional shamblers have no need to feed-a trait that comes in handy for a creature that often finds itself adrift or lost in strange realms where food and water doesn't-or perhaps cannot-exist. They are certainly most at home in regions that function similarly to most Material Plane worlds, for their bodies are built to traverse the ground. They have no inborn ability to fly, cannot breathe water, and possess no unusual resistance to energies, and as such there are many realms throughout the Great Beyond that are dangerous or even deadly to dimensional shamblers. Yet they are masters of traveling the planes, and instinctively avoid appearing in regions that would cause them harm. More powerful dimensional shamblers often seek out magical devices to aid them in traveling the stranger and less hospitable corners of reality.\n\nThe need a dimensional shambler has for exploring the Great Beyond isn't fully understood by mortal scholars. Certainly, curiosity seems to be a large part of their drive-a dimensional shambler can spend weeks or even years simply observing a particularly unusual planar feature, such as the expulsion of raw protolife from the Positive Energy Plane into the surrounding realities, the strange semianimate heavings of an Abyssal swamp giving birth to a legion of demons, or the mind-numbing violence of a reality storm deep in the Maelstrom. As chaotic evil outsiders, they are most comfortable on planes that either have no strong alignment traits or are close to chaotic evil, yet this doesn't prevent them from exploring realms beyond.\n\nThe mind of a dimensional shambler, as with its body and mobility, isn't quite \"in tune\" with mortal expectations, and it may be that what scholars have assumed is curiosity could be some other driving force. Perhaps the race instinctively travels the Great Beyond in search of a forgotten or hidden goal, or maybe the constant change of reality is something that brings them pleasure or some strange nutrition.\n\nDimensional shamblers generally lack the wits to carry on long philosophical discussions, and are prone to attacking other creatures when they encounter them, so attempts to learn more about this mysterious race through conversation have not resulted in particularly informative results.","habitat_society":"Dimensional shamblers seem to have very little interest in others of their kind. While they don't display any instinctual need for violence against others of their ilk when chance brings them together, neither do they seek out their own kind for companionship.\n\nDimensional shamblers are solitary beings, and the majority of their interactions with other forms of life are violent- they are fond of snatching creatures who are capable of comprehending their own peril and whisking them away to remote corners of the multiverse.\n\nThose few who have endured these abductions and survived to tell the tale did so either by escaping their captors and hiding, or by slaying the shamblers. In all cases, their return home has involved harrowing journeys through the Great Beyond, for the dimensional shambler is frustratingly skilled at selecting particularly remote and dangerous realms as destinations for its abductions. The fate of the majority of these victims is unknown, although circumstantial evidence indicates that the shambler itself plays a key and grisly role in the victims' doom.\n\nSpellcasters have long sought to harness the dimensional shambler's ability to accurately travel between planes.\n\nMortal magic has traditionally found this feat a difficult one to master-plane shift isn'torious for its inaccuracy, often leaving powerful effects like gate, miracle, or wish as the favored methods of safe interplanar travel. Yet the dimensional shambler seems able to navigate the unnavigable with ease, traveling between incredibly diverse and distant locations with no more difficulty than a human might have stepping out of a house into his own front yard. Unfortunately, the same mastery over dimensional travel that affords shamblers such accurate navigation allows them to resist the call of conjurers with surprising skill.\n\nIn fact, by the time most spellcasters master the magic required to lure or conjure a dimensional shambler, it is often a simpler matter to use a gate spell instead.\n\nSome conjurers claim to have developed methods of attracting dimensional shamblers more easily.\n\nThrough the use of blood sacrifice via a blade of purest metal and the application of exacting mathematical symbols or other complex combinations of runes, these spellcasters can call upon dimensional shamblers with relative ease. Unfortunately, the exact combination of runes, metals, and bloodshed seems different for every dimensional shambler, so once a spellcaster discovers the correct combination to lure one of these monsters, the secret that caster has uncovered is as closely guarded as her greatest treasures. The nature and availability of these secret rituals are left to the GM to determine, but such a ritual's recipe could well be worth 8,000 gp or more to an interested party."},{"name":"Dire Tiger","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+2 Dex, +6 natural, -1 size","hp":105,"hd":"14d8+42","hdvalue":14,"fort":12,"ref":11,"will":2,"speed":[{"type":"land","speed":40}],"melee":"2 claws +18 (2d4+8 plus grab), bite +18 (2d6+8/19-20 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +18, 2d4+8"}],"strength":27,"dexterity":15,"constitution":17,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":10,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite, claw)"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Perception","value":12},{"skill":"Stealth","value":15,"special":"+23 in tall grass"},{"skill":"Swim","value":13}],"environments":["any forests","any plains","any swamps"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This large tiger grumbles a warning as it crouches. Two saberlike fangs jut downward from its powerful jaws.","group":"Tiger","source":"PFRPG Bestiary","description":"Tigers stand more than 3 ft. tall at the shoulder and are about 9 ft. long. They weigh from 400 to 600 pounds. Tigers are usually the top animal predators in their territories, and have been known to kill bears, crocodiles, giant snakes, wolves, and even other great cats. Even humanoids are far from safe, especially in cases where a tiger has developed a taste for humanoid flesh. Tigers prefer terrain with plenty of cover and proximity to water as their hunting grounds. While the tiger itself is a fearsome predator, its strength and ferocity pales in comparison to that of the larger dire tiger. Known to many scholars as the smilodon and to tribal societies as the saber-toothed tiger, the dire tiger is invariably one of the region's top predators. Its defining feature is a pair of huge incisors that hang down like fearsome knives from the upper jaw, protruding menacingly even when the creature's mouth is shut. These immense hunting cats grow to be over 12 ft. long and can weigh up to 6,000 pounds.","ecology":"","habitat_society":""},{"name":"Drowning Devil","cr":8,"xp":4800,"alignment":"LE","size":"Large","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"},{"type":"see invisibility"}],"auras":["heavy aura (10 ft., DC 18)"],"ac":21,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+7 Dex, +1 dodge, +4 natural, -1 size","hp":103,"hd":"9d10+54","hdvalue":9,"fort":12,"ref":10,"will":7,"dr":"5/good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":19,"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"bite +15 (2d6+5), 2 slams +15 (1d8+5 plus poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"drown"},{"type":"poison"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"},{"spell":"water breathing"}]},{"frequency":"at-will","spells":[{"spell":"control water"},{"spell":"curse water"},{"spell":"discern lies"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"hydraulic push"}]},{"frequency":"1/day","spells":[{"spell":"freedom of movement"},{"spell":"summon","details":"level 4, 1 drowning devil 35%"}]},{"frequency":"3/day","spells":[{"spell":"hydraulic torrent"},{"spell":"poison"},{"spell":"protection from good"}]}],"strength":20,"dexterity":25,"constitution":23,"intelligence":16,"wisdom":20,"charisma":19,"baseatk":9,"cmb":3,"cmd":17,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Weapon Finesse"},{"feat":"Wind Stance"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":16},{"skill":"Fly","value":5},{"skill":"Intimidate","value":16},{"skill":"Knowledge (nature)","value":15},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":15},{"skill":"Swim","value":25}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Hell)"],"organizations":["solitary","pair","guard (3-10)"],"treasure":"standard","description_visual":"This serpentine creature has finlike wings, ram horns, four eyes, and arms that end in masses of tentacles.","group":"Devil","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Drown","kind":"Su","details":"As a full-round action, a drowning devil can summon murky water into the lungs of a single target within 30 ft. If the target can't breathe water, it's unable hold its breath and immediately begins to drown. At the start of its next turn, the target must succeed at a DC 18 Fortitude save to cough up this water or it falls unconscious and is brought to 0 hit points. On the next round, the target must save successfully again or drop to -1 hit point and start dying; on the third round it must save successfully again or die. The save DC is Charisma-based."},{"type":"Heavy Aura","kind":"Su","details":"Whenever a creature enters the drowning devil's heavy aura, it must succeed at a DC 18 Will save or reduce its speed as if carrying a load one step higher or wearing armor one category heavier (whichever is worse), and its armor check penalty increases by 2. A creature already carrying a heavy load or wearing heavy armor that fails its save can't move as long as it remains in the affected area. A creature that saves against a drowning devil's heavy aura is immune to that devil's aura for 24 hours. The save DC is Charisma-based."},{"type":"Poison","kind":"Ex","details":"Slam-injury; save Fort DC 20; frequency 1/round for 6 rounds; effect 1d4 Str; cure 2 consecutive saves."}],"description":"Called sarglagons in their Infernal tongue, drowning devils take great pride in being the best-adapted guardians of Hell's waterways, and are among the few fiends who travel the seas and rivers of the multiverse as part of larger infernal plots. Even in the air or on the ground, a drowning devil moves with a haunting litheness as though it were swimming. A typical drowning devil weighs 600 pounds, and can exceed 15 ft. from head to tail.","ecology":"","habitat_society":""},{"name":"Efreeti","cr":8,"xp":4800,"alignment":"LE","size":"Large","type":"outsider","subtypes":["extraplanar","fire"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"}],"ac":21,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+3 Dex, +1 dodge, +8 natural, -1 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":7,"ref":10,"will":9,"immunities":["fire"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"2 slams +15 (1d8+6 plus 1d6 fire) or mwk falchion +16 (2d6+9/18-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"change size"},{"type":"heat"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"plane shift","details":"willing targets to elemental planes, Astral Plane, or Material Plane only"},{"spell":"produce flame"},{"spell":"pyrotechnics"},{"spell":"scorching ray"}]},{"frequency":"1/day","spells":[{"spell":"gaseous form"},{"spell":"grant up to 3 wishes","details":"to nongenies only"},{"spell":"permanent image"}]},{"frequency":"3/day","spells":[{"spell":"invisibility"},{"spell":"quickened scorching ray"},{"spell":"wall of fire"}]}],"strength":23,"dexterity":17,"constitution":18,"intelligence":12,"wisdom":14,"charisma":15,"baseatk":10,"cmb":17,"cmd":31,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Quicken Spell-Like Ability (scorching ray)"}],"skills":[{"skill":"Bluff","value":19},{"skill":"Craft (any one)","value":14},{"skill":"Disguise","value":10},{"skill":"Fly","value":13},{"skill":"Intimidate","value":15},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":8}],"languages":["Auran","Aquan","Common","Ignan","Terran","telepathy 100 ft."],"sq":[{"type":"change shape","details":"humanoid or giant, alter self or giant form I"}],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","company (3-6)","band (7-12)"],"treasure":"standard (mwk falchion, other gear)","description_visual":"This muscular giant has crimson skin, smoldering eyes, and small black horns. Smoke rises in curls from its flesh.","group":"Genie","source":"PFRPG Bestiary","special_abilities":[{"type":"Change Size","kind":"Sp","details":"Twice per day, an efreeti can magically change a creature's size. This works just like an enlarge person or reduce person spell (the efreeti chooses when using the ability), except that the ability can work on the efreeti. A DC 13 Fortitude save negates the effect. The save DC is Charisma-based. This is the equivalent of a 2nd-level spell."},{"type":"Heat","kind":"Ex","details":"An efreeti's body deals 1d6 points of fire damage whenever it hits in melee, or in each round it grapples."}],"description":"The efreet (singular efreeti) are genies from the Plane of Fire. An efreeti stands about 12 ft. tall and weighs about 2,000 pounds. Efreet have few allies among geniekind. They certainly hate djinn, and attack them on sight. They hold an equally strong enmity for marids, and view the jann as frail and weak. Efreet often work closely with shaitans, yet even then alliances are temporary at best. A small percentage of efreet are noble. Noble efreet, often called maliks, have 13 Hit Dice and gain the following spell-like abilities: 3/day-fireball, heat metal; 1/day-greater invisibility, pyroclastic storm (as ice storm, with fire instead of cold damage). A noble efreeti's caster level for its spell-like abilities is 15th. Noble efreet are CR 10.","ecology":"","habitat_society":""},{"name":"Ember Weaver","cr":8,"xp":4800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["psychopomp","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"spiritsense","modifier":"60 ft."}],"auras":["eerie radiance (300 ft., DC 19)"],"ac":22,"ac_touch":16,"ac_flat_footed":16,"ac_mods":"+5 Dex, +1 dodge, +6 natural","hp":104,"hd":"11d8+55","hdvalue":11,"fort":11,"ref":8,"will":12,"dr":"10/adamantine","immunities":["charm","death effects","disease","fire","poison","spells with the light descriptor"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"sr":19,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 touches +15 (4d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rush of souls"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"continual flame"},{"spell":"dancing lights"},{"spell":"searing light"},{"spell":"suggestion"},{"spell":"whispering wind"}]},{"frequency":"1/day","spells":[{"spell":"dispel magic"},{"spell":"fly"},{"spell":"freedom of movement"},{"spell":"locate creature"},{"spell":"plane shift"},{"spell":"slay living"}]}],"strength":19,"dexterity":21,"constitution":18,"intelligence":18,"wisdom":21,"charisma":18,"baseatk":11,"cmb":15,"cmd":30,"feats":[{"feat":"Ability Focus (suggestion)"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Mobility"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Fly","value":23},{"skill":"Knowledge (geography)","value":18},{"skill":"Knowledge (planes)","value":18},{"skill":"Knowledge (religion)","value":18},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":18},{"skill":"Survival","value":19}],"languages":["Abyssal","Celestial","Infernal"],"sq":[{"type":"spirit touch"}],"environments":["any (Astral Plane)"],"organizations":["solitary","pair","escort (1 ember weaver and 1 shoki)","troupe (1 ember weaver plus 3-10 ahmuuths, catrinas, esoboks, or nosois)","procession (3-12 ember weavers)"],"treasure":"standard","description_visual":"This slim, glowing figure is draped with voluminous gossamer shawls and veils that obscure its shape.","group":"Psychopomp","source":"Monster Summoner's Handbook","special_abilities":[{"type":"Eerie Radiance","kind":"Su","details":"As a standard action, an ember weaver can wreath itself in an aura of cinders similar to dancing lights (CL 11th). Any living or dead creature within 300 ft. with line of sight to the dancing embers must succeed at a DC 19 Will save or else any protections or immunities it has against charm, fear, and mind-affecting effects are suppressed for as long as the ember weaver uses a free action to maintain the effect each round and for 1 round thereafter. Once a creature succeeds at this saving throw, it can't be affected by an eerie radiance for 24 hours. The light has no effect on psychopomps, creatures that can't see, and creatures the ember weaver chooses to exclude. This is a sight-based abjuration effect."},{"type":"Rush of Souls","kind":"Su","details":"As a standard action every 1d4+1 rounds, an ember weaver can call forth a rush of souls to trample its foes. This ability deals 6d6 points of force damage to all creatures in a 60-foot cone. A successful DC 19 Reflex saving throw halves the damage. The save DC is Charisma-based."}],"description":"Ember weavers are beacons for dead souls seeking the afterlife, and escorts for other psychopomps. Most ember weavers patrol graveyards, ley lines, and other places where the dead enter into the river of souls, beckoning them to step toward eternity. Ember weavers also perform services in payment for knowledge about lost souls.\n\nEmber weavers lead ahmuuths and esoboks in hunts for spirits waylaid by undeath. They also accompany nosois and catrinas to recover confused or rebellious spirits.","ecology":"","habitat_society":""},{"name":"Emperor Walrus","cr":8,"xp":4800,"alignment":"N","size":"Gargantuan","type":"animal","init":-1,"senses":[{"type":"low-light vision"}],"ac":20,"ac_touch":5,"ac_flat_footed":20,"ac_mods":"-1 Dex, +15 natural, -4 size","hp":126,"hd":"12d8+72","hdvalue":12,"fort":14,"ref":7,"will":8,"speed":[{"type":"land","speed":20},{"type":"swim","speed":60}],"melee":"bite +16 (4d6+15/19-20) or slam +15 (2d6+15 plus trip)","space":"20 ft.","reach":"15 ft.","strength":31,"dexterity":9,"constitution":22,"intelligence":2,"wisdom":15,"charisma":6,"baseatk":9,"cmb":23,"cmd":32,"cmd_special":"can't be tripped","feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":16},{"skill":"Swim","value":22}],"sq":[{"type":"hold breath"}],"environments":["cold oceans"],"organizations":["solitary","pair","herd (1-3 and 5-20 walruses)"],"treasure":"none","description_visual":"Thick folds of skin protect this massive sea mammal like fleshy armor. Tusks as tall as humans jut from its whiskered face.","group":"Walrus","source":"PFRPG Bestiary 4","description":"Towering over common walruses, emperor walruses live in only the most secluded arctic areas. They might be throwbacks to an earlier age of giant animals or bred by druids to be superior arctic predators. They often live in the company of common walruses, but are far more aggressive, driving off or killing any potential threats to the herd. Emperor walruses have a similar diet to common walruses, but may also eat giant crabs, seals, large fish, and seabirds. A full-grown male emperor walrus measures 20 ft. in length and weighs around 16 tons, with tusks up to 6 ft. long. It can live up to 80 years.","ecology":"","habitat_society":""},{"name":"Erinyes Devil","cr":8,"xp":4800,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"},{"type":"true seeing"}],"ac":23,"ac_touch":17,"ac_flat_footed":16,"ac_mods":"+6 Dex, +1 dodge, +6 natural","hp":94,"hd":"9d10+45","hdvalue":9,"fort":11,"ref":12,"will":7,"dr":"5/good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":19,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"+1 longsword +15 (1d8+8/19-20)","ranged":"+1 flaming composite longbow +14 (1d8+6/x3 plus 1d6 fire) or rope +15 touch (entangle)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"fear","details":"single target"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"minor image"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 3, 2 bearded devils, 50%"}]}],"strength":20,"dexterity":23,"constitution":21,"intelligence":14,"wisdom":18,"charisma":21,"baseatk":9,"cmb":14,"cmd":31,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge","type":"bonus"},{"feat":"Mobility","type":"bonus"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Shot on the Run"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":14},{"skill":"Escape Artist","value":12},{"skill":"Fly","value":19},{"skill":"Intimidate","value":17},{"skill":"Knowledge (planes)","value":8},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":15}],"languages":["Celestial","Common","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Hell)"],"organizations":["solitary","trio"],"treasure":"triple (+1 longsword, +1 flaming composite longbow [+5  Str bonus], rope)","description_visual":"Some calamity has befallen this angelic warrior. Wings stained black shear the air as her merciless eyes search for a target.","group":"Devil","source":"PFRPG Bestiary","special_abilities":[{"type":"Entangle","kind":"Su","details":"Each erinyes carries a 50-foot-long rope that entangles opponents of any size as an animate rope spell (CL 16th, DC 20). An erinyes can hurl its rope 30 ft. with no range penalty. An erinyes's rope functions only for the erinyes who made it and no other. The save DC is Dexterity-based."}],"description":"Known by many names-the Fallen, the Ash Wings, and the Furies-the devils called erinyes mock the form of the angelic hosts in their exaction of vengeance and bloody justice. Executioners, not judges, erinyes alight upon the bladed eaves of Dis, Hell's cosmopolitan second layer, ever attentive for chances to soar into battle, whether in defense of Hell, on the whims of diabolical masters, or at the impassioned summons of jilted mortal summoners. All erinyes weave deadly living ropes from their own hair, which they use in battle to lift their foes into the air, mocking and condemning their victims for their transgressions before dropping them from great heights.\n\nErinyes appear as darkly beautiful angels, augmenting their sensuality with deliberate bruises and scars. Yet despite their beauty, erinyes are not seducers-they lack the subtlety and patience required for such fine emotional manipulations, and instead vastly prefer to solve their problems with swift and excruciating violence. Often, an erinyes will stay her hand before attempting to slay a foe simply so she can draw out the victim's suffering. Death is usually the only way to escape an erinyes's not-so-tender attentions, and the most powerful of these devils excel at keeping their enemies alive but helpless so as to extend their torment-many going as far as to keep their victims alive with magic. Rumors hold that the most powerful erinyes torturers have skills that allow their torment to continue even after their subject has died from their attentions.\n\nMost erinyes stand just under 6 ft. tall and weigh approximately 140 pounds, even with their blackfeathered wings that stretch over 10 ft. wide.","ecology":"","habitat_society":""},{"name":"Fallen","cr":8,"xp":4800,"alignment":"LE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":3,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":17,"ac_flat_footed":19,"ac_mods":"+4 armor, +4 deflection, +3 Dex, +1 shield","hp":93,"hd":"11d8+44","hdvalue":11,"fort":7,"ref":6,"will":10,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"resists":[{"type":"acid","value":5},{"type":"fire","value":5}],"weaknesses":["light sensitivity"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"longsword +10 (1d8/19-20 plus 2d6 negative energy and agent of despair), light shield +9 (1d3 plus 2d6 negative energy and agent of despair)","ranged":"longbow +11 (1d8/x3 plus 2d6 negative energy and agent of despair)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"agent of despair"},{"type":"curse of the unburied"},{"type":"phantom armaments"},{"type":"touch of the grave"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"deeper darkness"},{"spell":"telekinesis"}]}],"dexterity":16,"intelligence":13,"wisdom":17,"charisma":18,"baseatk":8,"cmb":11,"cmb_special":"+2 vs. sunder","cmd":28,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Combat Expertise"},{"feat":"Improved Shield Bash"},{"feat":"Improved Sunder"},{"feat":"Shield Slam"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Fly","value":10},{"skill":"Intimidate","value":18},{"skill":"Knowledge (religion)","value":10},{"skill":"Perception","value":17},{"skill":"Ride","value":10},{"skill":"Sense Motive","value":15},{"skill":"Survival","value":13}],"languages":["Common"],"environments":["any (Worldwound)"],"organizations":["solitary","squad (2-6)","platoon (7-16)"],"treasure":"none","description_visual":"This ghostly crusader floats just above the ground. Its translucent form would be harder to see if not for the twin motes of hellish red light staring out from behind its helmet.","source":"AP 75","special_abilities":[{"type":"Agent of Despair","kind":"Su","details":"A fallen's attacks can weaken a creature's resolve. Any creature that takes damage from a fallen's attacks must succeed at a DC 19 Will save or take a -4 penalty on saving throws against fear. If a creature that has immunity to fear fails this saving throw, its immunity is temporarily suppressed. This effect lasts as long as a creature still suffers damage taken from a fallen's attacks. This effect is removed if the creature is healed of all damage inflicted by a fallen. The save DC is Charisma-based."},{"type":"Curse of the Unburied","kind":"Su","details":"Once per day, a fallen can demand that a good-aligned cleric, paladin, or cleric whose deity is opposed to the creation of undead locate its remains and perform a funeral for it on holy ground (through specific use of consecrate or hallow). The target must succeed at a DC 19 Will save or take a -2 penalty to each of its ability scores. Each day, the target can attempt a new saving throw; success keeps the target from accruing an additional -2 penalty to each of its ability scores. No ability score can be reduced below 1 by this effect. The ability score penalties are removed immediately upon completing the funeral rites for the fallen. The target doesn't need to complete the rites personally, but it is responsible for seeing that they're carried out. The save DC is Charisma-based."},{"type":"Phantom Armaments","kind":"Su","details":"A fallen possesses a semblance of the gear it carried in life. A fallen's weapons and armor are formed of force, allowing the fallen to make physical attacks and wear protective armor. Though solid and formed of force, this gear cannot be disarmed or removed from the fallen. Arrows fired from the fallen's longbow vanish after dealing damage to their target."},{"type":"Rejuvenation","kind":"Su","details":"A fallen is tied to the place where it fell in battle or the location where its remains were dragged after it fell in combat. Unless slain permanently, it reforms there 2d4 days later. A fallen is permanently destroyed and its soul is released when funeral rites lasting at least 1 minute are performed on its remains while on consecrated or hallowed ground."},{"type":"Touch of the Grave","kind":"Su","details":"All of a fallen's melee and ranged attacks deal an additional 2d6 points of negative energy damage."}],"description":"The fallen were once sworn champions of the previous four crusades against the Worldwound to whom fate has perpetrated a cruel trick. Unable to receive Pharasma's judgment and receive whatever reward awaits them in the afterlife for the deeds they performed in life, they are the grim, ghostly remains of the men and women they once were. However, the fallen's original goal of valiantly marching into the Worldwound to save Golarion from the demonic tide has washed from their tortured minds, and is replaced instead by pain, sorrow, and hatred. Their fall in battle remains the greatest disappointment in their souls. Most fallen are still adorned in the battered and breached armor they died in and armed with the weapons they once carried into battle. Sentient and suffering, the fallen wander the Worldwound in search someone to end their misery by performing last rites.\n\nAt a glance, a fallen might be mistaken for a well-armed ghost or spectre, but even casual study reveals that their fiery eyes are not vacant, and they're anything but mindless. In battle, fallen move in an efficient and deliberate manner, and they are absolutely silent until they deign to speak in raspy, sepulchral tones.\n\nEcology\n\nUpon death, a soul normally enters the Great Beyond and travels to the Boneyard, and once there, travels to an appropriate Outer Plane to become a petitioner. Whatever fate befalls that petitioner, whether it is destroyed or its energies are released to create an outsider, it never returns to the Boneyard again. Spiritualists speculate that the Abyssal energies pervasive throughout the Worldwound have altered the planar structure of the region in such a way that in very rare cases, typically among the strong-willed, some souls instinctively react as if were on an Outer Plane already and never depart for the Boneyard. These are the fallen.\n\nThe fallen are spontaneously created, and are similar to ghosts but for one crucial difference-the fallen have no remaining unfinished business to tie them to the Material Plane aside from receiving a proper burial. Like many other types of undead, the fallen have an aversion to sunlight. They are incapable of becoming corporeal, but can open and close doors, hurl objects, and otherwise manifest their displeasure through the use of telekinesis, and their ghostly weapons still strike true and deal damage since they are made of force. A fallen can even shroud itself in darkness so tangible that most demons cannot penetrate it. When funeral rites are conducted upon the place where they died, the infusion of positive energy scours away the Abyssal taint. This localized restoration of the natural cosmological order allows the soul of the fallen to escape to the Great Beyond and thus receive judgment.\n\nThough they were crusaders in life, fallen typically avoid the demons of the Worldwound unless they happen upon an injured or distracted one. Their shame at dying by demonic claws and their tortured existence hinders their ability to strike at the demons in their current state. When fallen encounter mortals, they typically plead for release from their condition through burial. They don't give the mortals much time to decide for themselves, instead using their abilities to compel the mortals into service-or slaying them in anger and frustration.\n\nHabitat & Society\n\nThe fallen desire nothing but release from the Material Plane. Existence is agony and horror for the fallen, a state that they cannot end themselves. They are not evil for evil's sake, but their situation fills them with uncontrollable rage and they cannot help but resent the living and act selfishly to end their plight. Some fallen lie to would-be rescuers, promising to reveal great treasure near the place they died. Others attack outright if not helped, take hostages, or threaten reprisals against family members or other innocents. That the Worldwound is too dangerous for most adventurers is inconsequential to them-for when did the fallen ever waver when duty called? Some simply go mad and cannot be reasoned with. The most tragic and desperate of the fallen are those that cannot remember where they died.\n\nTheir dark nature notwithstanding, the fallen understand enough about the reality of their situation to call upon clerics and paladins to help them. They can manage to hold back their rage in these situations and refrain from attacking the one who can help end their plight, but this doesn't stop them from attacking a cleric's companions. Likewise, the fallen don't hinder those affected by their curse of the unburied ability.","ecology":"Upon death, a soul normally enters the Great Beyond and travels to the Boneyard, and once there, travels to an appropriate Outer Plane to become a petitioner. Whatever fate befalls that petitioner, whether it is destroyed or its energies are released to create an outsider, it never returns to the Boneyard again. Spiritualists speculate that the Abyssal energies pervasive throughout the Worldwound have altered the planar structure of the region in such a way that in very rare cases, typically among the strong-willed, some souls instinctively react as if were on an Outer Plane already and never depart for the Boneyard. These are the fallen.\n\nThe fallen are spontaneously created, and are similar to ghosts but for one crucial difference-the fallen have no remaining unfinished business to tie them to the Material Plane aside from receiving a proper burial. Like many other types of undead, the fallen have an aversion to sunlight. They are incapable of becoming corporeal, but can open and close doors, hurl objects, and otherwise manifest their displeasure through the use of telekinesis, and their ghostly weapons still strike true and deal damage since they are made of force. A fallen can even shroud itself in darkness so tangible that most demons cannot penetrate it. When funeral rites are conducted upon the place where they died, the infusion of positive energy scours away the Abyssal taint. This localized restoration of the natural cosmological order allows the soul of the fallen to escape to the Great Beyond and thus receive judgment.\n\nThough they were crusaders in life, fallen typically avoid the demons of the Worldwound unless they happen upon an injured or distracted one. Their shame at dying by demonic claws and their tortured existence hinders their ability to strike at the demons in their current state. When fallen encounter mortals, they typically plead for release from their condition through burial. They don't give the mortals much time to decide for themselves, instead using their abilities to compel the mortals into service-or slaying them in anger and frustration.","habitat_society":"The fallen desire nothing but release from the Material Plane. Existence is agony and horror for the fallen, a state that they cannot end themselves. They are not evil for evil's sake, but their situation fills them with uncontrollable rage and they cannot help but resent the living and act selfishly to end their plight. Some fallen lie to would-be rescuers, promising to reveal great treasure near the place they died. Others attack outright if not helped, take hostages, or threaten reprisals against family members or other innocents. That the Worldwound is too dangerous for most adventurers is inconsequential to them-for when did the fallen ever waver when duty called? Some simply go mad and cannot be reasoned with. The most tragic and desperate of the fallen are those that cannot remember where they died.\n\nTheir dark nature notwithstanding, the fallen understand enough about the reality of their situation to call upon clerics and paladins to help them. They can manage to hold back their rage in these situations and refrain from attacking the one who can help end their plight, but this doesn't stop them from attacking a cleric's companions. Likewise, the fallen don't hinder those affected by their curse of the unburied ability."},{"name":"Feeder In The Depths","cr":8,"xp":4800,"alignment":"LE","size":"Huge","type":"magical beast","init":2,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"keen scent"},{"type":"low-light vision"}],"auras":["blood feast (30 ft.)"],"ac":20,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+2 Dex, +10 natural, -2 size","hp":105,"hd":"10d10+50","hdvalue":10,"hp_mods":["blood feast"],"fort":12,"ref":9,"will":7,"resists":[{"type":"cold","value":20}],"sr":19,"speed":[{"type":"swim","speed":80}],"melee":"bite +15 (2d6+10/19-20 plus deadly bleeding)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"swift bite"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"blood biography","details":"on any creature bitten in the past day"}]},{"frequency":"1/day","spells":[{"spell":"summon monster V","details":"summons 1d4+1 hammerhead sharks or 1d3 great white sharks"}]}],"strength":24,"dexterity":15,"constitution":20,"intelligence":13,"wisdom":15,"charisma":14,"baseatk":10,"cmb":19,"cmd":31,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (bite)"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":19},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":20},{"skill":"Swim","value":15}],"languages":["Aklo","Aquan","Infernal"],"environments":["any oceans"],"organizations":["solitary"],"treasure":"none","description_visual":"An immense gray-and-white shark glides through the water, its piercing red eyes revealing a vicious intelligence.","source":"Monster Codex","special_abilities":[{"type":"Blood Feast","kind":"Su","details":"When a creature within 30 ft. of a feeder in the depths takes bleed damage (including ongoing damage), the feeder heals an equal amount of damage."},{"type":"Deadly Bleeding","kind":"Su","details":"A feeder in the depth's bite causes bleeding wounds that resist healing. The first bite that damages a creature deals 1d4 points of bleed damage, and each subsequent bite increases the amount of bleed by 1d4. Stopping the bleeding requires a successful DC 20 Heal check or the application of any magical healing. However, anyone attempting to cast a healing spell on a creature suffering from deadly bleeding must succeed at a DC 20 caster level check or the spell doesn't affect the bleeding creature. The save DC is Constitution-based."},{"type":"Keen Scent","kind":"Ex","details":"A feeder in the depths can notice creatures by scent in a 180-foot radius underwater, and can detect blood in the water at a distance of up to 1 mile."},{"type":"Swift Bite","kind":"Ex","details":"When making a full attack, a feeder in the depths can make a second bite attack at a -5 penalty."}],"description":"Feeders in the depths closely resemble ordinary sharks, but they are faster, stronger, and far more intelligent and malevolent. Feeders in the depths begin life as ordinary sharks, raised under the care of sahuagin priestesses. A would-be feeder feasts on the flesh of merfolk, sea elves, and other aquatic humanoids. As it dines on these sacrifices, the priestess chants blasphemous rituals, infusing the shark with malign power and the stolen intelligence of its victims. Over the course of 13 feedings over 13 midwinters, a new feeder in the depths arises.\n\nFeeders in the depths view themselves as equals to sahuagin, not as servants. They have no special affection for sharks, and can't communicate with them. Feeders act as loyal companions as long as they're respected and given the freedom to hunt. If not treated well, they rip their would-be masters apart and descend into the lightless depths of the ocean. Although able to breed, feeders in the depths give birth only to monstrosities or normal sharks, never to other feeders. A typical feeder in the depths is 24 ft. long and weighs 5,500 pounds.","ecology":"","habitat_society":""},{"name":"Festering Spirit","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["stench (DC 14, 10 rounds)"],"ac":18,"ac_touch":18,"ac_flat_footed":12,"ac_mods":"+2 deflection, +5 Dex, +1 dodge","hp":58,"hd":"9d8+18","hdvalue":9,"fort":5,"ref":8,"will":7,"defensive_abilities":["channel resistance +2","incorporeal"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"incorporeal touch +11 (1d4 Con damage plus slime)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"slime"},{"type":"trample","details":"1 Con plus slime, DC 16"}],"dexterity":20,"intelligence":6,"wisdom":12,"charisma":15,"baseatk":6,"cmb":11,"cmd":24,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Mobility"}],"skills":[{"skill":"Fly","value":9},{"skill":"Perception","value":13},{"skill":"Stealth","value":17}],"sq":[{"type":"ghost touch"}],"environments":["any land","any underground"],"organizations":["solitary","pair","gang (3-6)"],"treasure":"incidental","description_visual":"This ghostlike creature reeks of the grave and drips with putrescent goo.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Create Spawn","kind":"Su","details":"A humanoid creature killed by a festering spirit's Constitution damage becomes a festering spirit under the control of its killer in 1d4 days. Giving the corpse a proper burial (or cremation) prevents it from becoming a festering spirit."},{"type":"Ghost Touch","kind":"Su","details":"A festering spirit can manipulate corporeal objects that weigh up to 25 pounds as if those objects had the ghost touch special ability."},{"type":"Slime","kind":"Su","details":"A festering spirit's slime resembles the putrefying sludge of decaying corpses. Any creature that is hit by the spirit's incorporeal touch attack, passes through its square, or hits it with a natural weapon or unarmed strike must attempt a DC 16 Fortitude save. On a failure, the creature is nauseated for 1d4 rounds, and on a success the creature is staggered for 1 round. A festering spirit's slime persists on objects and creatures for 1d10 minutes but has no harmful effect after its initial contact. Creatures immune to poison or disease are immune to this ability. The save DC is Charisma-based."},{"type":"Trample","kind":"Ex","details":"The DC of a festering spirit's trample is Charisma-based."}],"description":"A festering spirit arises when a vile person's corpse is put in a mass grave, or when such a person is buried, exhumed, and placed in a charnel house or ossuary. The lingering hatred and evil of the dead mixes with the worst remnants of dozens of other people, creating a frustrated incorporeal shade of sickness, hate, and rot. Powerful mortals might arise as multiple festering spirits, each spawned from a different aspect of the original creature's personality. A festering spirit can't travel more than a mile from its remains. When left alone for long periods, a festering spirit usually wanders the halls and rooms near its burial site, destroying things, indulging in pranks, or trying to eat and drink anything it finds palatable (which falls through its incorporeal body to no effect). Its senses can barely detect these treats, though some adventurers report that strong alcohol and spicy foods can distract the spirit as it savors these sensations.","ecology":"","habitat_society":""},{"name":"Floodslain Arsinoitherium","cr":8,"xp":4800,"alignment":"CE","size":"Large","type":"undead","subtypes":["augmented animal"],"init":-1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":21,"ac_touch":8,"ac_flat_footed":21,"ac_mods":"+13 natural, -1 Dex, -1 size","hp":67,"hd":"9d8+27","hdvalue":9,"fort":10,"ref":5,"will":5,"defensive_abilities":["channel resistance +2"],"dr":"5/magic","immunities":["undead traits"],"resists":[{"type":"cold","value":10}],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"gore +15 (4d8+15)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"crashing waters"},{"type":"create spawn"},{"type":"drowning touch","details":"DC 16"},{"type":"panic","details":"DC 16"},{"type":"powerful charge","details":"4d8+15"},{"type":"trample","details":"2d8+13, DC 24"}],"strength":30,"dexterity":8,"intelligence":2,"wisdom":15,"charisma":14,"baseatk":6,"cmb":17,"cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Overrun"},{"feat":"Power Attack"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Perception","value":14},{"skill":"Swim","value":18}],"sq":[{"type":"flash flood"}],"environments":["any plains"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This wild-eyed, rhinolike creature lumbers along with splashing steps, water streaming from its pale, sagging, hide.","group":"Floodslain","source":"Belkzen Hold Of The Orc Hordes","description":"Collectively known as \"the after-storm\" by Belkzen natives, floodslain are victims of flash floods that have risen as undead. They're creatures of panic and despair, driven by anger, fear, and a yearning to drag others into the waters. Long after the floodwaters recede, floodslain continue spreading the miserable death that claimed them.\n\nFloodslain are similar in appearance to their original living forms, and are recognizable even in their waterlogged state. Many were gruesomely damaged by the floods that took their lives, though, their bodies battered and broken by rushing water and debris. The one feature common among all floodslain is wild, panicked eyes-a telltale sign of a death mired in shock and fear. Floodslain tend to drift toward lower ground, as if seeking the very water that transformed them. While this habitual migration makes them a contained threat in some areas, the relatively flat floodplains of Belkzen offer little resistance to the wandering undead. They can be found floating in major rivers, trapped in ravines and valleys, and staggering across flatlands, sometimes in large numbers. Floodslain that come close to living creatures try to drown them, and relentlessly follow those who flee. Targets who escape often draw the attention of yet more floodslain, eventually leading the undead to their homes. In great numbers, floodslain can slaughter small settlements.\n\nWhile many find the possibility of undead born from purely natural disasters to be disturbing in and of itself, theories from druids and scholars in Lastwall hold even more chilling implications. Given that floodslain are most common in eastern Belkzen yet are little known outside that region, it is suspected that the floodwater itself was cursed even before falling as snow, perhaps by the dark influence of Gallowspire. If the Whispering Tyrant's insidious reach could extend so far using only passing clouds, the crusaders of Lastwall might be facing a threat even more dire than they realize.","ecology":"","habitat_society":""},{"name":"Frightful Haunter","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["cowardice (30 ft.)"],"ac":16,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+3 deflection, +3 Dex","hp":60,"hd":"8d8+24","hdvalue":8,"hp_mods":["fast healing 0 (see special abilities)"],"fort":5,"ref":5,"will":9,"defensive_abilities":["channel resistance +3","incorporeal"],"immunities":["haunts"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"terrifying touch +9 (3d8 plus Will DC 17 or shaken)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create haunt"},{"type":"terrifying touch","details":"DC 17"}],"dexterity":17,"intelligence":15,"wisdom":17,"charisma":16,"baseatk":6,"cmb":6,"cmd":21,"feats":[{"feat":"Blind-Fight"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":11},{"skill":"Intimidate","value":13},{"skill":"Knowledge (history)","value":10},{"skill":"Knowledge (local)","value":13},{"skill":"Perception","value":17},{"skill":"Stealth","value":14},{"skill":"Survival","value":11}],"languages":["Common","Goblin"],"environments":["any"],"organizations":["solitary","pair","gang (3-6)"],"treasure":"none","description_visual":"The mist forms a roughly humanoid shape. Its features are indistinct, except for its clawed hands and hairy, fanged face.","source":"Monster Codex","special_abilities":[{"type":"Aura of Cowardice","kind":"Su","details":"A frightful haunter radiates a palpably daunting aura that causes all enemies within 30 ft. to take a -4 penalty on saving throws against fear effects. Creatures that are normally immune to fear lose that immunity while within 10 ft. of a frightful haunter with this ability."},{"type":"Create Haunt","kind":"Su","details":"A frightful haunter has so much rage and desire to create fear that it can actually create a haunt once per hour. Each haunt has a CR no greater than the frightful haunter's CR - 2, and often takes a form either tied to the location the frightful haunter selects for it or inspired by the victims the frightful haunter hopes to frighten. Unlike a typical haunt, those created by a frightful haunter are destroyed when neutralized, and fade away after a number of days equal to the creator's Hit Dice. A frightful haunter cannot have more than 1 haunt active per HD; if any haunt is created that exceeds that limit, the oldest active haunt is neutralized."},{"type":"Fear Eater","kind":"Su","details":"A frightful haunter has an amount of fast healing equal to the number of creatures within 30 ft. currently suffering from a fear effect."},{"type":"Made of Fear","kind":"Su","details":"A frightful haunter is immune to the effects of a haunt, even those it doesn't create."},{"type":"Terrifying Touch","kind":"Su","details":"A creature struck by a frightful haunter's touch attack takes 3d8 points of damage and must succeed at a DC 17 Will saving throw or be shaken for 1 minute. A creature that succeeds at the save can't be made shaken by the terrifying touch for 24 hours, but can still take damage from it. Successfully using terrifying touch multiple times extends only the duration of its effect; it doesn't create a stronger fear condition. This is a mind-affecting fear effect. The DC is Charisma-based."}],"description":"Occasionally, the desire to cause fear and misery survives even when a bugbear dies. Such a creature can detach part of its vile nature to create frightening spiritual traps in the form of haunts. Whenever possible, a frightful haunter learns about a group before building haunts to terrify it, and customizes the haunts' effects based on its victims' fears and weaknesses. If a frightful haunter is forced to confront a group directly, it attempts to create a stronghold of damaging haunts, attacking only when the group neutralizes one of the haunts, and then fleeing to another prepared location.","ecology":"","habitat_society":""},{"name":"Fungal Nymph","cr":8,"xp":4800,"alignment":"CG","size":"Medium","type":"plant","subtypes":["augmented fey"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["blinding beauty (30 ft., DC 21)"],"ac":23,"ac_touch":21,"ac_flat_footed":19,"ac_mods":"+7 deflection, +4 Dex, +2 natural","hp":84,"hd":"8d8+48","hdvalue":8,"fort":15,"ref":17,"will":16,"defensive_abilities":["poisonous blood (DC 20)"],"dr":"10/cold iron","immunities":["disease","plant traits"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":10}],"melee":"slam +8 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"poison spore cloud","details":"DC 20"},{"type":"stunning glance","details":"DC 21"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dimension door"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":7,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":4,"spell_slots":1,"spells":[{"spell":"command plants"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"call lightning"},{"spell":"speak with plants"},{"spell":"spike growth"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"chill metal"},{"spell":"flame blade"},{"spell":"resist energy"},{"spell":"summon swarm"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"entangle"},{"spell":"faerie fire"},{"spell":"obscuring mist"},{"spell":"pass without trace"},{"spell":"produce flame"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"resistance"},{"spell":"virtue"}]}],"strength":14,"dexterity":19,"constitution":22,"intelligence":16,"wisdom":17,"charisma":25,"baseatk":4,"cmb":8,"cmd":27,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Casting"},{"feat":"Self-Sufficient"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Craft (alchemy)","value":14},{"skill":"Diplomacy","value":18},{"skill":"Escape Artist","value":15},{"skill":"Heal","value":13},{"skill":"Knowledge (dungeoneering)","value":11},{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":15},{"skill":"Survival","value":5},{"skill":"Swim","value":10}],"languages":["Common","Sylvan","Undercommon"],"sq":[{"type":"fungal metabolism"},{"type":"inspiration"},{"type":"rejuvenation"},{"type":"unearthly grace"},{"type":"wild empathy","details":"+21"}],"environments":["any ruins","any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"Mushroom caps and mold sprout from the pallid skin of this lithe female figure, and spores waft from her fungal gills.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Blinding Beauty","kind":"Su","details":"This ability affects all humanoids within 30 ft. of a nymph. Those who look directly at a nymph must succeed on a DC 21 Fortitude save or be blinded permanently. A nymph can suppress or resume this ability as a free action. The save DC is Charisma-based."},{"type":"Inspiration","kind":"Su","details":"A nymph can choose an intelligent creature to inspire and serve as a muse by giving that creature some token of her affection (typically a lock of her hair). As long as the nymph retains her favor for this creature and as long as the creature carries the nymph's token, the creature gains a +4 insight bonus on all Will saving throws, Craft checks, and Perform checks. A bard who has a nymph for a muse in this way can use his bardic performance for an additional number of rounds per day equal to his nymph muse's Charisma modifier. The nymph retains a link to her token and its carrier as if she had cast a status spell on the carrier. The nymph can end this effect at any time as a free action. A single nymph may only inspire one creature at a time in this manner. Spells A nymph casts spells as a 7th-level druid, but cannot swap out prepared spells to cast summon spells."},{"type":"Stunning Glance","kind":"Su","details":"As a standard action, a nymph can stun a creature within 30 ft. with a look. The target must succeed on a DC 21 Fortitude save or be stunned for 2d4 rounds. The save DC is Charisma-based."},{"type":"Unearthly Grace","kind":"Su","details":"A nymph adds her Charisma modifier as a racial bonus on all her saving throws, and as a deflection bonus to her Armor Class."},{"type":"Wild Empathy","kind":"Su","details":"This works like the druid's wild empathy class feature, except the nymph has a +6 racial bonus on the check. The nymph's effective druid level is equal to her HD for determining her total modifer to the check."}],"description":"A fungal creature is an animate plant with the appearance of a living creature. It grows from spores implanted in the dead body of a host creature, and takes on the host creature's basic form and many of that creature's abilities. It retains none of the memories of the creature it grew from, yet it instinctively knows how to use the abilities it inherited from its host. How exactly this is possible is a question that continues to befuddle scholars. The leading theory is that the spores' precise modeling of their host succeeds in capturing some of the creature's physiology-essentially copying its mind-but that for some reason the departure of the creature's spirit or soul upon death prevents the spores from copying the memories as well. Fungal creatures are often content to sit in quiet contemplation, absorbing the nutrients they require from the life-giving earth. But when faced with living creatures, the overwhelming biological need to reproduce takes over, and the fungal creatures try to seed their spores into new hosts to spawn the next generation of fungal creatures. Fungal creatures have the general appearance of the base creatures from which they spawned, but their skin is pale fungus rather than flesh and blood. Mushroom caps and shelf fungi sprout from a fungal creature's body, along with fungal gills to deliver the fungal creature's spores. As with many types of fungi, a fungal creature's flesh is poisonous, and any creature that ingests any part of a fungal creature's body risks infection by its spores (as described in the create spawn ability and fungal spores poison). The fungal nymph presented here is built using the nymph.","ecology":"","habitat_society":""},{"name":"Gammenore","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","subtypes":["cold"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":22,"ac_touch":10,"ac_flat_footed":21,"ac_mods":"+1 Dex, +12 natural, -1 size","hp":102,"hd":"12d10+36","hdvalue":12,"fort":11,"ref":11,"will":7,"defensive_abilities":["shell of ice"],"immunities":["cold"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"claw +17 (1d6+6/19-20), pincer +17 (2d6+9 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"2d6+9"},{"type":"ice spikes"},{"type":"oversized pincer"}],"strength":23,"dexterity":12,"constitution":16,"intelligence":3,"wisdom":16,"charisma":7,"baseatk":12,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":30,"cmd_special":"+12 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":14},{"skill":"Perception","value":10},{"skill":"Stealth","value":8,"special":"+16 in icy or snowy terrain"}],"environments":["any cold"],"organizations":["solitary","pair","cluster (3-9)"],"treasure":"none","description_visual":"Spikes of ice jut from the carapace of this stocky crustacean. It scuttles sideways on its eight legs with surprising speed, while its two pincers-one small and sharp, the other monstrously large- flex in anticipation of combat.","source":"AP 89","special_abilities":[{"type":"Ice Spikes","kind":"Su","details":"As a standard action, a gammenore can force freezing water through pores in its carapace to produce long, sharp spikes of ice. These spikes impale nearby creatures, dealing 6d6 points of piercing damage to each creature adjacent to the gammenore (Reflex DC 19 half). Additionally, the spikes shatter easily, embedding shards of ice in the flesh of creatures that fail their saving throws against the attack-these shards deal 1d6 points of bleed damage each round until the wounds are healed. A gammenore can use this ability once every 1d4 rounds. The save DC is Constitution-based."},{"type":"Oversized Pincer","kind":"Ex","details":"A gammenore's pincer attack is a primary attack that deals the indicated amount of damage plus 1-1/2 times its Strength modifier."},{"type":"Shell of Ice","kind":"Su","details":"Much of a gammenore's carapace is encased in a thick layer of jagged icicles. This shell of ice functions much like spiked armor, dealing 1d8 points of piercing damage to the target of any successful grapple combat maneuver check made by the gammenore. Additionally, this frozen shell helps to regulate the gammenore's cold body temperature, granting it resistance 10 to fire. The shell can absorb up to 60 points of fire damage before melting. Once the shell melts, the gammenore takes a -4 penalty to its natural armor bonus, it loses its fire resistance, and it deals no additional damage when grappling. A gammenore can reconstitute a melted shell by spending time in areas of intense cold. This process takes 2 hours in a cold environment, 3d10 minutes in areas of severe cold, and 1d10 minutes in areas of extreme cold."}],"description":"The gammenore is a prime example of how Triaxian fauna has adapted to survive the planet's long, cruel winters. While other creatures struggle to survive the planet's decades-long season of cold and ice, the gammenore thrives, turning the might of winter into the very tools of its survival.\n\nAbsent its icy armor, the gammenore looks like a large, blue-and-white-shelled crustacean. It has a rather wide,\n\noval-shaped carapace, a pair of powerful pincers, and four pairs of strong, articulated legs.\n\nA gammenore's two pincers serve very different purposes. The primary claw is monstrously large and extremely strong, and is used to break through ice and crush the gammenore's prey. The other claw is smaller, less cumbersome, and sharp enough to rend flesh and bone. The gammenore uses this smaller claw to tear its victims into pieces small enough to eat, and to perform any manipulations too delicate for the large claw. Its eyes are located on short stalks that rise from the front of its carapace, allowing it to see even when encased in its shell of ice. A gammenore is approximately 8 ft. wide, and weighs between 2,000 and 3,000 pounds.\n\nEcology\n\nDespite their resemblance to mundane crabs, gammenores are primarily terrestrial creatures, living in water only as larvae and while mating. They can be found anywhere ice and snow exists on Triaxus, from the high mountains to the low snowy plains, or even atop the ice-covered seas. The gammenore is an ambush predator, preferring to conceal itself in snow banks or among ice formations and wait for prey to approach. Once a victim is within reach, the gammenore erupts from hiding and attempts to grab or cripple the target with its large claw. Failing that, it may chase down its prey on foot, especially if the victim seems injured or the terrain favors climbing over sprinting. When times are lean, a gammenore may resort to scavenging or even to stealing food from larger predators, trusting its shell to protect it from enemies' reprisals.\n\nWhen threatened, a gammenore forces freezing water through pores in its shell to form a barrier of spikes across its carapace. These spikes break and fuse together over time to form a thick sheet of jagged ice over much of the gammenore's body, granting it a second layer of defense against attacks. A gammenore is able to excrete more water this way than it should theoretically be able to carry within its body, leading many scholars to conclude that much of the ice is magically produced or conjured. Despite this, gammenores seem to possess an unquenchable thirst, spending much of their time eating snow and ice. The creatures also prefer to eat their food frozen, letting victims' torn bodies freeze before crunching away at their meals.\n\nHabitat & Society\n\nDuring Triaxus's harsh winters, gammenores rarely spend much time in each other's company, as they are extremely competitive and fight each other for food or territory. Their behavior changes drastically as the season begins to turn- they become much more companionable as winter's grip on the land weakens. As spring nears, gammenores from across Triaxus instinctively begin to migrate to the nearest\n\nbody of water to mate and lay their eggs. These eggs then go dormant during the planet's long summer, hatching as the water temperature begins to drop once again. After laying their eggs, gammenores migrate to the coldest, most remote parts of the world. This is a time of danger for the civilized races of Triaxus, for gammenore migration routes are hardly regular each season and often cross through populated areas. In the northern stretches of the Allied Territories, inhabitants tell tales of armies of gammenores, over a hundred strong, marching through cities and leaving naught but rubble and ruin. These stories are most likely exaggerations, as gammenores rarely travel in groups larger than nine, but such packs of migrating gammenores can still wreak havoc on a community.\n\nAt the end of the gammenores' journey, they gather by the hundreds atop the tallest mountains and in the deepest caverns of the world to flee the coming heat. Near the planet's north pole these colonies can grow into the thousands, covering swaths of land in a living blanket of gammenores. Piled atop each other, the gammenores extend their ice shells to cover their entire bodies, encasing themselves in ice and slowing their metabolisms in an attempt to preserve themselves. Precipitation during the tail end of winter combines with the gammenore's own supernatural cold to further cement the creatures together, forming miniature glaciers and mountain icecaps to protect the colony from the heat of the planet's long summer.\n\nThis defense is far from perfect and few gammenores survive to the next winter. During particularly hot summers, gammenores on the periphery of the colony thaw prematurely. These gammenores either die quickly from the heat, or stumble into glacial runoff and are washed downstream, becoming short-lived menaces to riverside communities. Summertime gammenores react to heat dangers as though they were one category more severe-normal temperatures count as hot conditions, hot conditions count as severe heat, etc. The high temperatures of summer also disorient the gammenores, giving them the confused condition. Gammenores in the heat lose their shell of ice ability entirely, and produce sprays of cold water from their bodies in place of ice spikes, allowing them to attempt a single combat maneuver check to bull rush all adjacent creatures once every 1d4 rounds. Reduce the CR of a gammenore encountered in the summertime by 2.\n\nGammenore eggs hatch in late fall, releasing swarms of larvae into the waters in which they were deposited. These larvae feed upon each other, and on anything the current washes them across, until they mature into adult gammenores at the start of winter. Meanwhile, the adults that survived the summer chip themselves free from their communal glaciers to seek new hunting grounds away from their competitive kin, so that they can feed and restore their strength.","ecology":"Despite their resemblance to mundane crabs, gammenores are primarily terrestrial creatures, living in water only as larvae and while mating. They can be found anywhere ice and snow exists on Triaxus, from the high mountains to the low snowy plains, or even atop the ice-covered seas. The gammenore is an ambush predator, preferring to conceal itself in snow banks or among ice formations and wait for prey to approach. Once a victim is within reach, the gammenore erupts from hiding and attempts to grab or cripple the target with its large claw. Failing that, it may chase down its prey on foot, especially if the victim seems injured or the terrain favors climbing over sprinting. When times are lean, a gammenore may resort to scavenging or even to stealing food from larger predators, trusting its shell to protect it from enemies' reprisals.\n\nWhen threatened, a gammenore forces freezing water through pores in its shell to form a barrier of spikes across its carapace. These spikes break and fuse together over time to form a thick sheet of jagged ice over much of the gammenore's body, granting it a second layer of defense against attacks. A gammenore is able to excrete more water this way than it should theoretically be able to carry within its body, leading many scholars to conclude that much of the ice is magically produced or conjured. Despite this, gammenores seem to possess an unquenchable thirst, spending much of their time eating snow and ice. The creatures also prefer to eat their food frozen, letting victims' torn bodies freeze before crunching away at their meals.","habitat_society":"During Triaxus's harsh winters, gammenores rarely spend much time in each other's company, as they are extremely competitive and fight each other for food or territory. Their behavior changes drastically as the season begins to turn- they become much more companionable as winter's grip on the land weakens. As spring nears, gammenores from across Triaxus instinctively begin to migrate to the nearest\n\nbody of water to mate and lay their eggs. These eggs then go dormant during the planet's long summer, hatching as the water temperature begins to drop once again. After laying their eggs, gammenores migrate to the coldest, most remote parts of the world. This is a time of danger for the civilized races of Triaxus, for gammenore migration routes are hardly regular each season and often cross through populated areas. In the northern stretches of the Allied Territories, inhabitants tell tales of armies of gammenores, over a hundred strong, marching through cities and leaving naught but rubble and ruin. These stories are most likely exaggerations, as gammenores rarely travel in groups larger than nine, but such packs of migrating gammenores can still wreak havoc on a community.\n\nAt the end of the gammenores' journey, they gather by the hundreds atop the tallest mountains and in the deepest caverns of the world to flee the coming heat. Near the planet's north pole these colonies can grow into the thousands, covering swaths of land in a living blanket of gammenores. Piled atop each other, the gammenores extend their ice shells to cover their entire bodies, encasing themselves in ice and slowing their metabolisms in an attempt to preserve themselves. Precipitation during the tail end of winter combines with the gammenore's own supernatural cold to further cement the creatures together, forming miniature glaciers and mountain icecaps to protect the colony from the heat of the planet's long summer.\n\nThis defense is far from perfect and few gammenores survive to the next winter. During particularly hot summers, gammenores on the periphery of the colony thaw prematurely. These gammenores either die quickly from the heat, or stumble into glacial runoff and are washed downstream, becoming short-lived menaces to riverside communities. Summertime gammenores react to heat dangers as though they were one category more severe-normal temperatures count as hot conditions, hot conditions count as severe heat, etc. The high temperatures of summer also disorient the gammenores, giving them the confused condition. Gammenores in the heat lose their shell of ice ability entirely, and produce sprays of cold water from their bodies in place of ice spikes, allowing them to attempt a single combat maneuver check to bull rush all adjacent creatures once every 1d4 rounds. Reduce the CR of a gammenore encountered in the summertime by 2.\n\nGammenore eggs hatch in late fall, releasing swarms of larvae into the waters in which they were deposited. These larvae feed upon each other, and on anything the current washes them across, until they mature into adult gammenores at the start of winter. Meanwhile, the adults that survived the summer chip themselves free from their communal glaciers to seek new hunting grounds away from their competitive kin, so that they can feed and restore their strength."},{"name":"Gargoyle Guardian","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"construct","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":22,"ac_touch":11,"ac_flat_footed":20,"ac_mods":"+2 Dex, +11 natural, -1 size","hp":90,"hd":"11d10+30","hdvalue":11,"fort":3,"ref":5,"will":3,"dr":"5/adamantine","immunities":["construct traits"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"1 bite +16 (1d8+6), 2 claw +16 (1d6+6)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"snatch"}],"strength":22,"dexterity":14,"wisdom":10,"charisma":1,"baseatk":11,"cmb":18,"cmd":30,"skills":[{"skill":"Stealth","value":2}],"sq":[{"type":"freeze"}],"environments":["any land"],"organizations":["solitary","wing (2-8)"],"treasure":"none","description_visual":"The head of this sinisterly carved statue of a devil slowly scans its surroundings, every motion making the faint sound of stone grinding upon stone.","source":"AP 48","special_abilities":[{"type":"Freeze","kind":"Ex","details":"A gargoyle guardian can hold itself so still that it appears to be a statue. A gargoyle guardian that uses freeze can take 20 on Stealth checks to hide in plain sight as a stone statue."},{"type":"Snatch","kind":"Ex","details":"A gargoyle guardian can start a grapple when it hits with both claw attacks, as though it had the grab ability. If it grapples a creature of size Medium or smaller, it squeezes each round for automatic claw damage with a successful grapple check. A gargoyle guardian can fly while holding a creature that weighs 350 pounds or less. It cannot throw creatures it is carrying, but can drop them as a free action."}],"description":"Many races adorn their buildings and structures with carved gargoyles to make them look more fearsome, to ward off evil spirits, or in the hope of making real gargoyles think another tribe is already occupying the area. Many magic-users also create constructs in the shapes and forms of gargoyles, emulating those creatures' ability to blend in with stone structures and taking advantage of the pervasiveness of sculpted gargoyles to create stealthy protectors and watchdogs.\n\nMany spellcasters construct gargoyle guardians that have special abilities, making them even more capable and vigilant sentinels.\n\nGargoyle Sentry (+0 CR): These gargoyle guardians are created with eyes of citrine linked to a 1-foot-diameter orb of the same stone. The orb always displays what the gargoyle guardian sees, though without the construct's darkvision or low-light vision. If the gargoyle sentry is destroyed, its eyes and the linked orb shatter into worthless dust.\n\nConstruction A gargoyle guardian's body is made from 1,000 pounds of dense stone-typically of the colors and designs of the structure or memorial it is meant to guard-and treated with 1,000 gp worth of rare minerals and precious filigree.\n\nGargoyle Guardian CL 10th; Price 30,000 gp; 50,000 gp (sentry) Construction Requirements Craft Construct, animate objects, stone shape, geas/quest; Cost 15,000 gp; 25,000 gp (sentry)","ecology":"","habitat_society":""},{"name":"Giant Octopus","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"animal","subtypes":["aquatic"],"init":6,"senses":[{"type":"low-light vision"}],"ac":18,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+2 Dex, +7 natural, -1 size","hp":90,"hd":"12d8+36","hdvalue":12,"fort":11,"ref":12,"will":7,"defensive_abilities":["ink cloud (30-foot-radius sphere)"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"speed_mod":"jet 200 ft.","melee":"bite +13 (1d8+5 plus poison), 8 tentacles +11 (1d4+2 plus grab)","space":"10 ft.","reach":"10 ft. (20 ft. with tentacle)","special_attacks":[{"type":"constrict","details":"tentacle, 1d4+2"}],"strength":20,"dexterity":15,"constitution":17,"intelligence":2,"wisdom":12,"charisma":3,"baseatk":9,"cmb":15,"cmb_special":"+4 vs. grapple","cmd":27,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack","type":"bonus"},{"feat":"Skill Focus (Stealth)"},{"feat":"Stealthy"}],"skills":[{"skill":"Escape Artist","value":18},{"skill":"Perception","value":8},{"skill":"Stealth","value":18},{"skill":"Swim","value":13}],"environments":["any oceans"],"organizations":["solitary"],"treasure":"incidental","description_visual":"A storm of tentacles, each twenty ft. in length, flails with deadly precision from the leathery body of this gigantic octopus.","group":"Octopus","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 19; frequency 1/round for 6 rounds; effect 1d3 Str; cure 2 saves."}],"description":"The giant octopus is a true monster capable of catching and eating sharks, humans, or anything else it can grab with its tentacles.","ecology":"","habitat_society":""},{"name":"Giant Slug","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"vermin","init":-4,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":20,"ac_touch":4,"ac_flat_footed":20,"ac_mods":"-4 Dex, +16 natural, -2 size","hp":102,"hd":"12d8+48","hdvalue":12,"fort":12,"ref":0,"will":4,"dr":"10/slashing or piercing","immunities":["acid","mind-affecting effects"],"weaknesses":["susceptible to salt"],"speed":[{"type":"land","speed":20}],"melee":"tongue +15 (2d10+12 plus 2d8 acid)","ranged":"spit acid +3 (10d6 acid)","space":"15 ft.","reach":"15 ft.","strength":27,"dexterity":2,"constitution":18,"wisdom":10,"charisma":1,"baseatk":9,"cmb":19,"cmd":25,"cmd_special":"can't be tripped","sq":[{"type":"malleable"}],"environments":["temperate marshes","any underground","warm marshes"],"organizations":["solitary"],"treasure":"none","description_visual":"This massive, gray-brown slug leaves a viscous trail of slime in its wake as a long rasping tongue tastes the air for prey.","group":"Slug","source":"PFRPG Bestiary","special_abilities":[{"type":"Spit Acid","kind":"Ex","details":"A giant slug can spit acid at an opponent within 60 ft. (no range increment). With a successful ranged touch attack, the target takes 10d6 points of acid damage (no save)."},{"type":"Malleable","kind":"Ex","details":"A giant slug's body is very malleable, allowing it to fit into narrow areas with ease. A giant slug takes no penalty to its speed or checks when squeezing in an area that is one size category smaller than its actual size (10 ft. wide for most giant slugs). A giant slug can squeeze normally through an area two size categories smaller than its actual size (5 ft. wide for most giant slugs)."},{"type":"Susceptible to Salt","kind":"Ex","details":"A handful of salt burns a giant slug as if it were a flask of acid, causing 1d6 points of damage per use."}],"description":"No simple garden pests, giant slugs pose a serious threat to those caught in their path. Folk who dwell near swamps and other regions that support giant slugs risk losing livestock and even their homes to these enormous beasts. Giant slugs constantly wander in search of food, their preference being fleshy organic material, which they slice into smaller, easily gulped chunks with their rasp-like tongues.\n\nWhat strange inf luence might have caused the first giant slugs to grow to such monstrous proportions is unknown, but today, giant slugs breed true and birth their oversized offspring after a fleshy, squirming courtship ritual. After mating, a female giant slug lays just over a hundred eggs, each approximately a foot in diameter. The mother slug guards this clutch fiercely and aggressively attacks any creatures that wander too close. Giant slugs inhabiting swamps aboveground mate once a year, and those who live in the area know better than to go into the swamps during this month.\n\nDeep below ground, some subterranean races use giant slugs as mounts or guardians. Creatures like mites, who have a strange empathy with vermin, can be used to keep giant slugs docile, but in most cases, those who would use giant slugs must do so with great care, keeping them well fed until they are needed for battle. Frightened whispers report armies of troglodytes using giant slugs as siege mounts. One particularly disturbing tale mentions a vast underground cavern inhabited by scores of skum and aboleth-controlled aquatic giant slugs with strange, mind-numbing abilities infused into their acidic saliva.","ecology":"","habitat_society":""},{"name":"Giant Stymphalides","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","init":6,"senses":[{"type":"low-light vision"}],"ac":22,"ac_touch":11,"ac_flat_footed":20,"ac_mods":"+2 Dex, +11 natural, -1 size","hp":94,"hd":"9d10+45","hdvalue":9,"fort":11,"ref":10,"will":5,"dr":"10/magic and adamantine","immunities":["fire"],"weaknesses":["sonic"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":120,"maneuverability":"poor"}],"melee":"bite +14 (1d8+6 plus bleed/19-20), 2 talons +9 (1d6+3), 2 wings +9 (1d6+3 plus bleed)","ranged":"2 wing razors +10 (1d6+6 plus bleed)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"glare"},{"type":"wing razors"}],"strength":22,"dexterity":15,"constitution":20,"intelligence":2,"wisdom":15,"charisma":17,"baseatk":9,"cmb":16,"cmd":28,"feats":[{"feat":"Alertness"},{"feat":"Critical Focus"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Flyby Attack"}],"skills":[{"skill":"Fly","value":0},{"skill":"Perception","value":12}],"environments":["warm mountains"],"organizations":["solitary","pair","flight (3-9)"],"treasure":"Value incidental","description_visual":"Every feather like a plate of shimmering armor and its beak the length and sharpness of a knight's lance, this towering, ibis-like bird looks to be sculpted from silver and brass. Standing upon long legs ending in powerful metallic talons, its beady eyes dart about voraciously.","group":"Stymphalidies","source":"AP 26","special_abilities":[{"type":"Glare","kind":"Su","details":"As a standard action, in any area of normal or brighter light, a giant stymphalides can ruffle its metallic feathers in such a way as to dazzle all creatures nearby. Any creature within 30 ft. must make a DC 19 or be blinded for 1d6 minutes. A creature can defend against this effect in the same way it would a gaze attack. This is a sight-based effect. The DC is Constitution-based."},{"type":"Wing Razors","kind":"Ex","details":"A giant stymphalides's metallic feathers are razor-sharp. In addition to being able to slash creatures with its wings as a melee attack, it may beat its wings, flinging two large, feathered shards at a single target. These wing razors deal 2d6 points of damage and cause bleed. A giant stymphalides can use this attack a number of time per day equal to its Constitution modifier."}],"description":"Man-eating birds of prey, the rare creatures known as stymphalides stalk the arid plains and coastlines of Golarion in ravenous swarms, shredding warm-blooded animals and unwary travelers with their bladed feathers and dagger-like beaks. From a distance, stymphalides might easily be mistaken for cranes, ibises, or other longnecked birds, though in full sunlight their gleaming feathers and the haze of blood lingering from past meals are impossible to mistake. Peculiarly, the feathers and beak of a stymphalides are made of steel, similar to the metallic hide of a gorgon. The wings of stymphalides are as sharp as knives and often lacerate their prey as the birds swarm and beat their wings against their unfortunate victims' skin. Similarly, their beaks are supernaturally sharp and can pierce the tough hides of animal prey or the armor of those warriors foolish enough to hunt the creatures. Even if a victim of a stymphalides swarm's frenzied attacks manages to fend off the vicious creatures, the wounds caused by the birds continue to bleed long after being inflicted, and the victim often perishes from loss of blood before ever reaching help. Most stymphalides stand approximately 2-1/2 ft. tall and weigh little more than 40 pounds. Although mean-tempered and territorial, lone stymphalides prove relatively harmless, thus traveling in swarms of several dozen, relying on strength of numbers to bring down large or dangerous prey. Many tales also tell of enormous breeds of these monstrous birds, powerful enough to prey upon wyverns. These giant stymphalides are said to grow up to 13 ft. tall and weigh over 250 pounds, with wingspans reaching upward of 25 ft. Such gigantic stymphalides are rarely seen, preferring to lurk upon desolate cliffs or even amid harsh extraplanar realms. Ecology Unlike vultures and other birds of the deserts and plains, stymphalides don't scavenge carcasses, although they are not above driving away natural scavengers if a large, fresh kill looks particularly inviting. When traveling in flocks, stymphalides prove fearless predators, swooping in and swarming any creature that wanders into their territory. The birds actively hunt their prey, harrying and killing lone individuals or stragglers. The attacks of a stymphalides swarm often prove so vicious that the creatures can take to flight once they have wounded prey, wait for it to bleed to death, and return to pick the corpse clean. Stymphalides generally avoid attacking large groups of people, unless the birds have gathered in a particularly sizable flock. Stymphalides are not purely carnivorous. A lone stymphalides might resort to eating fruit and other plants if it is separated from its flock or food is scarce, and orchards and fields of crops have been devastated by stymphalides when great swarms of the birds, starving from overpopulation or lack of prey, migrate to new territories. Yet although the birds are omnivorous, they seem to prefer meat. Those plainsfolk or desert-dwellers whose livelihoods depend on livestock have learned to fear the sight of flocks of birds silhouetted against the sky, as herds of cattle and other grazing animals have been ravaged by their swarms. Habitat & Society Most swarms of stymphalides roost near watering holes, rivers, and coastal cliffs, preying upon unfortunate creatures desperate enough to seek food or water so near to the dangerous birds' nests. The nests of stymphalides are frequently made from the bones of the creatures' prey, piled into macabre ziggurats upon which entire flocks of the birds rest. Particularly large flocks of the birds construct enormous nests, and giant stymphalides can create towers visible for miles. When not at rest, flocks of the creatures soar high on warm currents of air, relying upon their keen eyesight to spot suitable prey far below. Because of their voracious appetites, flocks of stymphalides must claim a vast swath of territory to maintain their feeding habits. Stymphalides are fiercely territorial, and flocks of the birds frequently fight with one another in swooping aerial battles to determine possession of land. Fortunately for the folk of civilized lands, stymphalides rarely encroach upon areas well traveled by humanoids and other creatures clever enough to bring down one of these metal-winged avians. Among the people of the plains, the metallic birds are often regarded as nearly legendary creatures. Stymphalides breed at an astonishing rate, however, and overpopulation and exhaustion of game frequently force extraordinarily large and deadly groups of the creatures to band together in search of new lands and new prey to devour.","ecology":"Unlike vultures and other birds of the deserts and plains, stymphalides don't scavenge carcasses, although they are not above driving away natural scavengers if a large, fresh kill looks particularly inviting. When traveling in flocks, stymphalides prove fearless predators, swooping in and swarming any creature that wanders into their territory. The birds actively hunt their prey, harrying and killing lone individuals or stragglers. The attacks of a stymphalides swarm often prove so vicious that the creatures can take to flight once they have wounded prey, wait for it to bleed to death, and return to pick the corpse clean. Stymphalides generally avoid attacking large groups of people, unless the birds have gathered in a particularly sizable flock. Stymphalides are not purely carnivorous. A lone stymphalides might resort to eating fruit and other plants if it is separated from its flock or food is scarce, and orchards and fields of crops have been devastated by stymphalides when great swarms of the birds, starving from overpopulation or lack of prey, migrate to new territories. Yet although the birds are omnivorous, they seem to prefer meat. Those plainsfolk or desert-dwellers whose livelihoods depend on livestock have learned to fear the sight of flocks of birds silhouetted against the sky, as herds of cattle and other grazing animals have been ravaged by their swarms.","habitat_society":"Most swarms of stymphalides roost near watering holes, rivers, and coastal cliffs, preying upon unfortunate creatures desperate enough to seek food or water so near to the dangerous birds' nests. The nests of stymphalides are frequently made from the bones of the creatures' prey, piled into macabre ziggurats upon which entire flocks of the birds rest. Particularly large flocks of the birds construct enormous nests, and giant stymphalides can create towers visible for miles. When not at rest, flocks of the creatures soar high on warm currents of air, relying upon their keen eyesight to spot suitable prey far below. Because of their voracious appetites, flocks of stymphalides must claim a vast swath of territory to maintain their feeding habits. Stymphalides are fiercely territorial, and flocks of the birds frequently fight with one another in swooping aerial battles to determine possession of land. Fortunately for the folk of civilized lands, stymphalides rarely encroach upon areas well traveled by humanoids and other creatures clever enough to bring down one of these metal-winged avians. Among the people of the plains, the metallic birds are often regarded as nearly legendary creatures. Stymphalides breed at an astonishing rate, however, and overpopulation and exhaustion of game frequently force extraordinarily large and deadly groups of the creatures to band together in search of new lands and new prey to devour."}];
